class SimUnitsManager(core.UnitsManager):
    """
    !!!!! Warning !!!!!
    ! This is in preview state; please see the help for more info
    !!!!! Warning !!!!!
    
    Extends the base UnitsManager with helpers for converting simulation-specific
    unit enums into unit strings that the base UnitsManager methods accept.
    
    Use the inherited methods (evaluateExpression, convert, formatValue, etc.)
    for expression evaluation, unit conversion, and value formatting. The
    helper methods on this class translate typed enums (e.g. ForceUnits) into
    the string identifiers those inherited methods expect.
    
    Inherited methods that accept an optional units parameter
    (evaluateExpression, formatValue, standardizeExpression) default to
    the document's default length unit when units are omitted. Always
    pass an explicit unit string for non-length quantities.
    
    Internal values are held in SI units (e.g. seconds, radians, kg for time, angle, mass)
    with the exception that all lengths are in cm rather than meter and this affects derived
    units (e.g. force is kg * cm / s^2 -> 0.01N).
    """
    def __init__(self):
        pass
    @staticmethod
    def cast(arg) -> SimUnitsManager:
        return SimUnitsManager()
    def getForceUnitString(self, units: ForceUnits = ForceUnits.DefaultForceUnit) -> str:
        """
        Returns the unit string corresponding to the given force unit enum value.
        The returned string (e.g. "N", "lbforce") can be passed to base UnitsManager
        methods such as evaluateExpression, convert, and formatValue.
        units : Optional, the force unit to convert to a string.
        The unit string for the specified force unit, or null on error.
        With no argument: string for default force unit will be returned.
        """
        return str()

class SolveFuture(core.Future):
    """
    !!!!! Warning !!!!!
    ! This is in preview state; please see the help for more info
    !!!!! Warning !!!!!
    
    Represents the asynchronous result of a solve operation.
    This object is returned by Study.solve() and can be used to monitor
    the state of the solve, check for errors or warnings, and cancel the operation.
    """
    def __init__(self):
        pass
    @staticmethod
    def cast(arg) -> SolveFuture:
        return SolveFuture()
    def cancel(self) -> bool:
        """
        Cancels the solve operation if it is still in progress.
        This operation is not undoable.
        Returns true if the cancellation was successfully requested, false otherwise.
        """
        return bool()
    @property
    def isComplete(self) -> bool:
        """
        Returns true if the solve operation has completed, regardless of whether
        it succeeded or failed.
        """
        return bool()
    @property
    def isSucceeded(self) -> bool:
        """
        Returns true if the solve operation completed successfully with no errors.
        Returns false otherwise, including when the solve is still in progress.
        """
        return bool()
    @property
    def hasErrors(self) -> bool:
        """
        Returns true if the solve job completed with errors.
        Returns false otherwise, including when the solve is still in progress.
        """
        return bool()
    @property
    def hasWarnings(self) -> bool:
        """
        Returns true if the solve job completed with warnings.
        Returns false otherwise, including when the solve is still in progress.
        """
        return bool()
    @property
    def errors(self) -> str:
        """
        Returns any error messages from the solve operation.
        Returns an empty string if there are no errors or the solve is still in progress.
        """
        return str()
    @property
    def warnings(self) -> str:
        """
        Returns any warning messages from the solve operation.
        Returns an empty string if there are no warnings or the solve is still in progress.
        """
        return str()
    @property
    def progressPercentage(self) -> int:
        """
        The progress of the solve operation as a percentage value between 0 and 100.
        """
        return int()

